import{_ as o,a0 as p,w as n,s as l,ao as u,I as a,x as i,a1 as t,A as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"在 Linux 中运行特定命令而无需 sudo 密码 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中运行特定命令而无需 sudo 密码 | LCTT (201903) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中运行特定命令而无需 sudo 密码 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中运行特定命令而无需 sudo 密码 | LCTT (201903) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201903/20190214 Run Particular Commands Without Sudo Password In Linux","title":"在 Linux 中运行特定命令而无需 sudo 密码","tag":"201903","desc":""},"relativePath":"201903/20190214 Run Particular Commands Without Sudo Password In Linux.md","filePath":"[post].md"}'),c={name:"201903/20190214 Run Particular Commands Without Sudo Password In Linux.md"};function r(h,s,k,g,b,m){const e=p("Link");return n(),l("div",null,[s[15]||(s[15]=u(`<h1 id="在-linux-中运行特定命令而无需-sudo-密码" tabindex="-1">在 Linux 中运行特定命令而无需 sudo 密码 <a class="header-anchor" href="#在-linux-中运行特定命令而无需-sudo-密码" aria-label="Permalink to “在 Linux 中运行特定命令而无需 sudo 密码”">​</a></h1><p>我有一台部署在 AWS 上的 Ubuntu 系统，在它的里面有一个脚本，这个脚本的原有目的是以一定间隔（准确来说是每隔 1 分钟）去检查某个特定服务是否正在运行，如果这个服务因为某些原因停止了，就自动重启这个服务。但问题是我需要 sudo 权限来开启这个服务。正如你所知道的那样，当我们以 sudo 用户运行命令时，我们应该提供密码，但我并不想这么做，实际上我想做的是以 sudo 用户的身份运行这个服务但无需提供密码。假如你曾经经历过这样的情形，那么我知道一个简单的方法来做到这点。今天，在这个简短的指南中，我将教你如何在类 Unix 的操作系统中运行特定命令而无需 sudo 密码。</p><p>就让我们看看下面的例子吧。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkdir /ostechnix</span></span>
<span class="line"><span>[sudo] password for sk:</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/05/sudo-password-1.png" alt=""></p><p>正如上面的截图中看到的那样，当我在根目录（<code>/</code>）中创建一个名为 <code>ostechnix</code> 的目录时，我需要提供 sudo 密码。每当我们尝试以 sudo 特权执行一个命令时，我们必须输入密码。而在我的预想中，我不想提供 sudo 密码。下面的内容便是我如何在我的 Linux 机子上运行一个 <code>sudo</code> 命令而无需输入密码的过程。</p><h3 id="在-linux-中运行特定命令而无需-sudo-密码-1" tabindex="-1">在 Linux 中运行特定命令而无需 sudo 密码 <a class="header-anchor" href="#在-linux-中运行特定命令而无需-sudo-密码-1" aria-label="Permalink to “在 Linux 中运行特定命令而无需 sudo 密码”">​</a></h3><p>基于某些原因，假如你想允许一个用户运行特定命令而无需提供 sudo 密码，则你需要在 <code>sudoers</code> 文件中添加上这个命令。</p><p>假如我想让名为 <code>sk</code> 的用户去执行 <code>mkdir</code> 而无需提供 sudo 密码，下面就让我们看看该如何做到这点。</p><p>使用下面的命令来编辑 <code>sudoers</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo visudo</span></span></code></pre></div><p>将下面的命令添加到这个文件的最后。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sk ALL=NOPASSWD:/bin/mkdir</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/05/sudo-password-7.png" alt=""></p><p>其中 <code>sk</code> 是用户名。根据上面一行的内容，用户 <code>sk</code> 可以从任意终端执行 <code>mkdir</code> 命令而不必输入 sudo 密码。</p><p>你可以用逗号分隔的值来添加额外的命令（例如 <code>chmod</code>），正如下面展示的那样。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sk ALL=NOPASSWD:/bin/mkdir,/bin/chmod</span></span></code></pre></div><p>保存并关闭这个文件，然后注销（或重启）你的系统。现在以普通用户 <code>sk</code> 登录，然后试试使用 <code>sudo</code> 来运行这些命令，看会发生什么。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkdir /dir1</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/05/sudo-password-6.png" alt=""></p><p>看到了吗？即便我以 sudo 特权运行 <code>mkdir</code> 命令，也不会弹出提示让我输入密码。从现在开始，当用户 <code>sk</code> 运行 <code>mkdir</code> 时，就不必输入 sudo 密码了。</p><p>当运行除了添加到 <code>sudoers</code> 文件之外的命令时，你将被提示输入 sudo 密码。</p><p>让我们用 <code>sudo</code> 来运行另一个命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt update</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/05/sudo-password-4.png" alt=""></p><p>看到了吗？这个命令将提示我输入 sudo 密码。</p><p>假如你不想让这个命令提示你输入 sudo 密码，请编辑 <code>sudoers</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo visudo</span></span></code></pre></div><p>像下面这样将 <code>apt</code> 命令添加到 <code>sudoers</code> 文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sk ALL=NOPASSWD:/bin/mkdir,/usr/bin/apt</span></span></code></pre></div><p>你注意到了上面命令中 <code>apt</code> 二进制执行文件的路径与 <code>mkdir</code> 的有所不同吗？是的，你必须提供一个正确的可执行文件路径。要找到任意命令的可执行文件路径，例如这里的 <code>apt</code>，可以像下面这样使用 <code>whichis</code> 命令来查看：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ whereis apt</span></span>
<span class="line"><span>apt: /usr/bin/apt /usr/lib/apt /etc/apt /usr/share/man/man8/apt.8.gz</span></span></code></pre></div><p>如你所见，<code>apt</code> 命令的可执行文件路径为 <code>/usr/bin/apt</code>，所以我将这个路径添加到了 <code>sudoers</code> 文件中。</p><p>正如我前面提及的那样，你可以添加任意多个以逗号分隔的命令。一旦你做完添加的动作，保存并关闭你的 <code>sudoers</code> 文件，接着注销，然后重新登录进你的系统。</p><p>现在就检验你是否可以直接运行以 <code>sudo</code> 开头的命令而不必使用密码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt update</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/05/sudo-password-5.png" alt=""></p><p>看到了吗？<code>apt</code> 命令没有让我输入 sudo 密码，即便我用 <code>sudo</code> 来运行它。</p><p>下面展示另一个例子。假如你想运行一个特定服务，例如 <code>apache2</code>，那么就添加下面这条命令到 <code>sudoers</code> 文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sk ALL=NOPASSWD:/bin/mkdir,/usr/bin/apt,/bin/systemctl restart apache2</span></span></code></pre></div><p>现在用户 <code>sk</code> 就可以运行 <code>sudo systemctl restart apache</code> 命令而不必输入 sudo 密码了。</p><p>我可以再次让一个特别的命令提醒输入 sudo 密码吗？当然可以！只需要删除添加的命令，注销然后再次登录即可。</p><p>除了这种方法外，你还可以在命令的前面添加 <code>PASSWD:</code> 指令。让我们看看下面的例子：</p><p>在 <code>sudoers</code> 文件中添加或者修改下面的一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sk ALL=NOPASSWD:/bin/mkdir,/bin/chmod,PASSWD:/usr/bin/apt</span></span></code></pre></div><p>在这种情况下，用户 <code>sk</code> 可以运行 <code>mkdir</code> 和 <code>chmod</code> 命令而不用输入 sudo 密码。然而，当他运行 <code>apt</code> 命令时，就必须提供 sudo 密码了。</p><p>免责声明：本篇指南仅具有教育意义。在使用这个方法的时候，你必须非常小心。这个命令既可能富有成效但也可能带来摧毁性效果。例如，假如你允许用户执行 <code>rm</code> 命令而不输入 sudo 密码，那么他们可能无意或有意地删除某些重要文件。我警告过你了！</p><p>那么这就是全部的内容了。希望这个能够给你带来帮助。更多精彩内容即将呈现，请保持关注！</p><p>干杯！</p><hr>`,50)),a("p",null,[s[1]||(s[1]=i("via: ",-1)),t(e,{href:"https://www.ostechnix.com/run-particular-commands-without-sudo-password-linux/"},{default:d(()=>[...s[0]||(s[0]=[i("https://www.ostechnix.com/run-particular-commands-without-sudo-password-linux/",-1)])]),_:1})]),a("p",null,[s[6]||(s[6]=i("作者：",-1)),t(e,{href:"https://www.ostechnix.com/author/sk/"},{default:d(()=>[...s[2]||(s[2]=[i("SK",-1)])]),_:1}),s[7]||(s[7]=i(" 选题：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:d(()=>[...s[3]||(s[3]=[i("lujun9972",-1)])]),_:1}),s[8]||(s[8]=i(" 译者：",-1)),t(e,{href:"https://github.com/FSSlc"},{default:d(()=>[...s[4]||(s[4]=[i("FSSlc",-1)])]),_:1}),s[9]||(s[9]=i(" 校对：",-1)),t(e,{href:"https://github.com/wxy"},{default:d(()=>[...s[5]||(s[5]=[i("wxy",-1)])]),_:1})]),a("p",null,[s[12]||(s[12]=i("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...s[10]||(s[10]=[i("LCTT",-1)])]),_:1}),s[13]||(s[13]=i(" 原创编译，",-1)),t(e,{href:"https://linux.cn/"},{default:d(()=>[...s[11]||(s[11]=[i("Linux中国",-1)])]),_:1}),s[14]||(s[14]=i(" 荣誉推出",-1))])])}const C=o(c,[["render",r]]);export{w as __pageData,C as default};
